<template>
  <f7-page class="hg-dashboard-content not-found-page" @page:beforein="getAllData">
    <div class="not-found-page-content">
      <f7-block>
        <f7-block-title>{{ pageTitle }}</f7-block-title>
        <p class="unfortunately-text">{{ pageText }}</p>

        <div v-if="mathematician" class="mathematician">
          <div class="mathematician-avatar">
            <img :src="mathematicianImg" :alt="`${mathematician.img}`" />
            <p class="mathematician-name">{{ mathematician.name }}</p>
          </div>

          <p>{{ mathematician.bio }}</p>
        </div>
      </f7-block>
    </div>

    <bottom-menu :current-path="f7route.path" />
  </f7-page>
</template>

<script setup>
import { f7 } from "framework7-vue";
import { reactive, computed, watch } from "vue";
import { useNetwork } from "@vueuse/core";
import { useI18n } from "vue-i18n";
import BottomMenu from "@/components/bottom-menu.vue";

defineProps({
  f7route: {
    type: Object,
    default: () => {},
  },
});

const i18n = useI18n();

const mathematician = reactive({
  name: "",
  bio: "",
  img: "",
});
const network = reactive(useNetwork());

const pageTitle = computed(() => (network.isOnline ? i18n.t("not-found.title") : i18n.t("not-found.title-offline")));
const pageText = computed(() => (network.isOnline ? i18n.t("not-found.text") : i18n.t("not-found.text-offline")));
const mathematicianImg = computed(() => {
  if (!network.isOnline) {
    // load base64 when offline
    const mathematiciansImgObject = {
      Carl: "data:image/jpeg;base64,",
      Georg:
        "data:image/jpeg;base64,",
      Isaac:
        "data:image/jpeg;base64,",
      Grigori:
        "data:image/jpeg;base64,",
      Hypatia:
        "data:image/jpeg;base64,",
      Archimedes:
        "data:image/jpeg;base64,",
      Leonhard:
        "data:image/jpeg;base64,",
      Paul: "data:image/jpeg;base64,",
      Pythagoras:
        "data:image/jpeg;base64,",
      Terry:
        "data:image/jpeg;base64,",
    };

    return mathematiciansImgObject[mathematician.img];
  }

  return `/images/mathematicians/${mathematician.img}.jpg`;
});

const getAllData = () => {
  const index = Math.round(Math.random() * 9);

  mathematician.name = i18n.t(`not-found.mathematics.${index}.name`);
  mathematician.bio = i18n.t(`not-found.mathematics.${index}.bio`);
  mathematician.img = i18n.t(`not-found.mathematics.${index}.img`);
};

watch(
  () => network.isOnline,
  (value, oldValue) => {
    if (oldValue === false && value === true) {
      f7.views.main.router.navigate(f7.views.main.router.previousRoute.path);
    }
  },
);
</script>

<style lang="scss">
@import "../assets/scss/pages/not-found";
</style>
